INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/vchalk-education','vChalk Education — Learning Progress Tracking & Education Technology Platform','portfolio','published','{"category": "Educational Technology", "description": "Longitudinal learning progress, classroom assessment and teacher support in remedial education.", "body": "As Co-Founder and Chief Technology Officer, Anil Bishnoi was associated with the technology leadership of vChalk. Public reporting describes a platform connecting assessment records, individual student profiles and learning progress. These capabilities describe the company’s platform; they do not imply that Anil personally wrote every component.\n\nThe documented workflow supports teachers and assessment teams recording learning levels, attendance and skill development, then using reports to inform remedial teaching. Public recruitment material describes Android assessment tools and field data collection. Parent engagement included local-language IVRS calls. Pedagogy and programme operations were team responsibilities.\n\nHistorical growth ambitions are not presented as achieved outcomes. The public vChalk-Webapp repository contains a Drupal-based codebase; vChalk-OS contains Raspberry Pi boot and firmware files, while vChalk-EZY-app is empty. Those repository names alone do not establish a complete assessment application.", "role": "Co-Founder and Chief Technology Officer", "period": "From March 2015 · role documented in professional profile", "technologies": ["Android", "Drupal", "PHP", "JavaScript"], "features": ["Individual student profiles and learning-level records", "Attendance and skill-development tracking", "Assessment updates and longitudinal progress reporting", "Teacher and instructor support for remedial education", "Parent engagement through local-language IVRS"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}, {"label": "2016 NASSCOM Social Innovation Forum report · IT Voice", "url": "https://www.itvoice.in/nasscom-foundation-gives-inr-70-lakhs-in-grants-to-social-enterprises-and-ngos-2"}, {"label": "vChalk recruitment · Android assessment and field workflows", "url": "https://www.alterbeat.com/impact-executive-at-vchalk-education.html"}, {"label": "D-Prize · vChalk longitudinal learning progress", "url": "https://paul-youn.squarespace.com/winners/profiles/category/Year%3A%2B2014B"}, {"label": "Public vChalk Webapp repository", "url": "https://github.com/anibish/vChalk-Webapp"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"category": "Educational Technology", "description": "Longitudinal learning progress, classroom assessment and teacher support in remedial education.", "body": "As Co-Founder and Chief Technology Officer, Anil Bishnoi was associated with the technology leadership of vChalk. Public reporting describes a platform connecting assessment records, individual student profiles and learning progress. These capabilities describe the company’s platform; they do not imply that Anil personally wrote every component.\n\nThe documented workflow supports teachers and assessment teams recording learning levels, attendance and skill development, then using reports to inform remedial teaching. Public recruitment material describes Android assessment tools and field data collection. Parent engagement included local-language IVRS calls. Pedagogy and programme operations were team responsibilities.\n\nHistorical growth ambitions are not presented as achieved outcomes. The public vChalk-Webapp repository contains a Drupal-based codebase; vChalk-OS contains Raspberry Pi boot and firmware files, while vChalk-EZY-app is empty. Those repository names alone do not establish a complete assessment application.", "role": "Co-Founder and Chief Technology Officer", "period": "From March 2015 · role documented in professional profile", "technologies": ["Android", "Drupal", "PHP", "JavaScript"], "features": ["Individual student profiles and learning-level records", "Attendance and skill-development tracking", "Assessment updates and longitudinal progress reporting", "Teacher and instructor support for remedial education", "Parent engagement through local-language IVRS"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}, {"label": "2016 NASSCOM Social Innovation Forum report · IT Voice", "url": "https://www.itvoice.in/nasscom-foundation-gives-inr-70-lakhs-in-grants-to-social-enterprises-and-ngos-2"}, {"label": "vChalk recruitment · Android assessment and field workflows", "url": "https://www.alterbeat.com/impact-executive-at-vchalk-education.html"}, {"label": "D-Prize · vChalk longitudinal learning progress", "url": "https://paul-youn.squarespace.com/winners/profiles/category/Year%3A%2B2014B"}, {"label": "Public vChalk Webapp repository", "url": "https://github.com/anibish/vChalk-Webapp"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"title": "vChalk Education \u2014 Learning Progress Tracking & Education Technology Platform", "description": "Longitudinal learning progress, classroom assessment and teacher support in remedial education."}'::jsonb,'{"title": "vChalk Education \u2014 Learning Progress Tracking & Education Technology Platform", "description": "Longitudinal learning progress, classroom assessment and teacher support in remedial education."}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/education-lms-attendance','Learning Management & Digital Attendance Systems','portfolio','published','{"category": "Educational Technology", "description": "Historical LMS, Drupal integration and attendance work for schools and technical institutes.", "body": "The professional profile documents LMS development and digital attendance systems, including Drupal CMS/LMS integration with automated attendance. These are professional experience records, rather than separate verified contracts or customer endorsements.\n\nThe profile lists Swami Keshvanand Institute of Technology, Vivekananda Institute of Technology and Sri Balaji College of Engineering and Technology in Jaipur, and Modi Institute of Technology in Kota, for March 2010. It also lists Khalsa Academy School and Global Children’s Academy in Srinagar for September–October 2009, followed by work with smaller Rajasthan schools in 2011–2012.", "role": "LMS Developer · schools and technical institutes", "period": "September 2009 – April 2012", "technologies": ["Drupal", "LMS", "Attendance systems"], "features": ["Learning management systems", "CMS/LMS integration", "Digital attendance", "Automated attendance integration"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"category": "Educational Technology", "description": "Historical LMS, Drupal integration and attendance work for schools and technical institutes.", "body": "The professional profile documents LMS development and digital attendance systems, including Drupal CMS/LMS integration with automated attendance. These are professional experience records, rather than separate verified contracts or customer endorsements.\n\nThe profile lists Swami Keshvanand Institute of Technology, Vivekananda Institute of Technology and Sri Balaji College of Engineering and Technology in Jaipur, and Modi Institute of Technology in Kota, for March 2010. It also lists Khalsa Academy School and Global Children’s Academy in Srinagar for September–October 2009, followed by work with smaller Rajasthan schools in 2011–2012.", "role": "LMS Developer · schools and technical institutes", "period": "September 2009 – April 2012", "technologies": ["Drupal", "LMS", "Attendance systems"], "features": ["Learning management systems", "CMS/LMS integration", "Digital attendance", "Automated attendance integration"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"title": "Learning Management & Digital Attendance Systems", "description": "Historical LMS, Drupal integration and attendance work for schools and technical institutes."}'::jsonb,'{"title": "Learning Management & Digital Attendance Systems", "description": "Historical LMS, Drupal integration and attendance work for schools and technical institutes."}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/mediatek-android-kernel','MediaTek — Android Kernel Engineering','portfolio','published','{"category": "Mobile Applications", "description": "Project-based Android kernel development documented in the professional profile.", "body": "Anil’s profile records a remote, project-based Android Kernel Developer engagement with MediaTek. The available profile establishes the role and dates, but does not provide public product names, implementation details or performance results. Those details are intentionally not inferred.", "role": "Android Kernel Developer · project based, remote", "period": "January – September 2011", "technologies": ["Android", "Kernel engineering"], "features": [], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"category": "Mobile Applications", "description": "Project-based Android kernel development documented in the professional profile.", "body": "Anil’s profile records a remote, project-based Android Kernel Developer engagement with MediaTek. The available profile establishes the role and dates, but does not provide public product names, implementation details or performance results. Those details are intentionally not inferred.", "role": "Android Kernel Developer · project based, remote", "period": "January – September 2011", "technologies": ["Android", "Kernel engineering"], "features": [], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": true, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"title": "MediaTek \u2014 Android Kernel Engineering", "description": "Project-based Android kernel development documented in the professional profile."}'::jsonb,'{"titl