INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/isys-solutions','ISYS Solutions — Rural Technology & Training Systems','portfolio','published','{"category": "Historical Professional Work", "description": "Founder-led technology initiatives combining rural engineering and multimedia training infrastructure.", "body": "The profile describes rural technology initiatives, engineering systems and an Ubuntu-based virtual training multimedia server. It records work with DC sewing machines and regenerative braking in a rural training context. The founder role included technical systems development and training quality standards.\n\nThese are profile-documented initiatives. No unverified commercial results or current operational claims are attached.", "role": "Founder", "period": "April 2012 – June 2013", "technologies": ["Ubuntu", "Multimedia systems"], "features": ["Virtual training multimedia server", "Rural engineering systems", "Training quality standards"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": false, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"category": "Historical Professional Work", "description": "Founder-led technology initiatives combining rural engineering and multimedia training infrastructure.", "body": "The profile describes rural technology initiatives, engineering systems and an Ubuntu-based virtual training multimedia server. It records work with DC sewing machines and regenerative braking in a rural training context. The founder role included technical systems development and training quality standards.\n\nThese are profile-documented initiatives. No unverified commercial results or current operational claims are attached.", "role": "Founder", "period": "April 2012 – June 2013", "technologies": ["Ubuntu", "Multimedia systems"], "features": ["Virtual training multimedia server", "Rural engineering systems", "Training quality standards"], "sources": [{"label": "Professional profile · Anil Bishnoi", "url": "https://www.linkedin.com/in/anilbishnoi3/"}], "featured": false, "project_status": "Historical professional work", "mode": "enhance"}'::jsonb,'{"title": "ISYS Solutions \u2014 Rural Technology & Training Systems", "description": "Founder-led technology initiatives combining rural engineering and multimedia training infrastructure."}'::jsonb,'{"title": "ISYS Solutions \u2014 Rural Technology & Training Systems", "description": "Founder-led technology initiatives combining rural engineering and multimedia training infrastructure."}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
