INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/anibish-platform','Anibish — Software Engineering Studio Platform','portfolio','published','{"category": "Web & SaaS Applications", "description": "The studio’s own public website and operational workspaces.", "body": "The Anibish platform combines a public service catalogue and enquiry capture with administrative content management, project workflows, private business correspondence and sandbox billing. Its public source provides direct evidence of the implementation. Financial processing remains sandbox only. Individual module verification is recorded in the project documentation rather than implied by the presence of a screen.", "role": "Studio owner and software engineer", "period": "", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "Redis", "Docker"], "features": ["Public service catalogue and lead capture", "Versioned content and legal policies", "Customer and project workspaces", "Private administrative Email Centre", "Sandbox invoices and payment records"], "sources": [{"label": "Public source repository", "url": "https://github.com/anibish/anibish"}], "featured": true, "project_status": "Live · continuing development", "mode": "enhance"}'::jsonb,'{"category": "Web & SaaS Applications", "description": "The studio’s own public website and operational workspaces.", "body": "The Anibish platform combines a public service catalogue and enquiry capture with administrative content management, project workflows, private business correspondence and sandbox billing. Its public source provides direct evidence of the implementation. Financial processing remains sandbox only. Individual module verification is recorded in the project documentation rather than implied by the presence of a screen.", "role": "Studio owner and software engineer", "period": "", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "Redis", "Docker"], "features": ["Public service catalogue and lead capture", "Versioned content and legal policies", "Customer and project workspaces", "Private administrative Email Centre", "Sandbox invoices and payment records"], "sources": [{"label": "Public source repository", "url": "https://github.com/anibish/anibish"}], "featured": true, "project_status": "Live · continuing development", "mode": "enhance"}'::jsonb,'{"title": "Anibish \u2014 Software Engineering Studio Platform", "description": "The studio\u2019s own public website and operational workspaces."}'::jsonb,'{"title": "Anibish \u2014 Software Engineering Studio Platform", "description": "The studio\u2019s own public website and operational workspaces."}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
