-- Source-backed public professional facts requested by the owner. Existing manual records are never overwritten.
SELECT 'freelance-delivery-history','136 completed Fiverr orders','experience','published',v,v,'{}','{}',now()
FROM (SELECT '{"description":"136 completed Fiverr orders, verified in the owner’s completed-order history on 16 November 2026. Repeat orders may belong to the same engagement; this is not a count of unique projects or positive reviews.","completed_order_count":136,"verified_on":"2026-11-16","evidence_visibility":"private","mode":"enhance"}'::jsonb v) s
ON CONFLICT(slug) DO NOTHING;
